The intrinsic convexity parameter
$\mu_\psi$
of a convex function $\psi$ is defined as the largest scalar $\mu$ such that $\psi(\cdot)-\mu\|\cdot\|^2/2$ is convex.


    Let $\R$ denote the set of real numbers.
    Let $ \R_+ $ (resp., $ \R_{++} $) denote the set of non-negative real numbers (resp., the set of positive real numbers).
	Let $\R^n$ denote the standard $n$-dimensional Euclidean space equipped with  inner product and norm denoted by $\left\langle \cdot,\cdot\right\rangle $
	and $\|\cdot\|$, respectively. 


	Let $\log(\cdot)$ denote the natural logarithm.

	For given $\Phi: \R^n\rightarrow (-\infty,+\infty]$, let $\dom \Phi:=\{x \in \R^n: \Phi (x) <\infty\}$ denote the effective domain of $\Phi$ 
	and $\Phi$ is proper if $\dom \Phi \ne \emptyset$.
	A proper function $\Phi: \R^n\rightarrow (-\infty,+\infty]$ is $\mu$-convex for some $\mu \ge 0$ if
	\[
	\Phi(\alpha x+(1-\alpha) y)\leq \alpha \Phi(x)+(1-\alpha)\Phi(y) - \frac{\alpha(1-\alpha) \mu}{2}\|x-y\|^2
	\]
	for every $x, y \in \dom \Phi$ and $\alpha \in [0,1]$.
Let $\mConv{n}$ denote the set of all proper lower semicontinuous $\mu$-convex functions.
 We simply denote $\mConv{n}$ by $\bConv{n}$ when $\mu=0$.
	For $\varepsilon \ge 0$, the \emph{$\varepsilon$-subdifferential} of $ \Phi $ at $x \in \dom \Phi$ is denoted by
	\[
        \partial_\varepsilon \Phi (x):=\left\{ s \in\R^n: \Phi(y)\geq \Phi(x)+\left\langle s,y-x\right\rangle -\varepsilon, \forall y\in\R^n\right\}.
        \]
	We denote the subdifferential of $\Phi$ at $x \in \dom \Phi$ by $\partial \Phi (x)$, which is the set  $\partial_0 \Phi(x)$ by definition.
    For a given subgradient
$\Phi'(x) \in \partial \Phi(x)$, we denote the linearization of convex function $\Phi$ at $x$ by $\ell_\Phi(\cdot,x)$, which is defined as
\begin{equation}\label{linfdef}
\ell_\Phi(\cdot,x)=\Phi(x)+\langle \Phi'(x),\cdot-x\rangle.
\end{equation}

We assume that 
\begin{itemize}


\item[(A1)] $f, h \in \bConv{n}$ are such that
		$\dom h \subset \dom f$, and a subgradient oracle,
		 i.e.,
		a function $f':\dom h \to \R^n$
		satisfying $f'(x) \in \partial f(x)$ for every $x \in \dom h$, is available;
		\item[(A2)]
		there exists $(M_f,L_f)\in \R^2_+$ such that for every $x,y \in \dom h$,
		\[
		\|f'(x)-f'(y)\| \le 2M_f + L_f \|x-y\|;
		\]
\item[(A3)]
		the set of optimal solutions $X_*$ of
		problem \eqref{eq:ProbIntro2} is nonempty.
\end{itemize}


It is known that that (A2) implies that for every $x,y \in \dom h$, 
\begin{equation}\label{ineq:est} 	
f(x)-\ell_f(x;y) \le 2M_f \|x-y\| + \frac{L_f}{2} \| x-y \|^2.
	\end{equation}

Our goal in this section is to describe two completely universal methods for solving \eqref{eq:ProbIntro2}  and describe  their iteration-complexity guarantees for finding 
a $\bar \varepsilon$-solution $\bar x$ of \eqref{eq:ProbIntro2}, i.e., 
a point $\bar  x$ such that $\phi(\bar x) - \phi_* \le \bar \varepsilon$, in terms of
$(M_f,L_f,\mu_\phi )$, $\bar \varepsilon$, and $d_0$, where $d_0$
is the distance of the initial iterate $\hat x_0$ with respect to $X_*$, i.e.,
\begin{equation}\label{defd0}
d_0 := \min \{\|x-\hat x_0\| : x \in X_*\}.
\end{equation}

	U-CS($\hat x_0,\chi,\lam_0,\bar \varepsilon$)

	\noindent\rule[0.5ex]{1\columnwidth}{1pt}

    {\bf Input:} $(\hat x_0,\chi,\lam_0,\bar \varepsilon)\in \dom h \times [0,1) \times \R_{++} \times \R_{++}$.
        \begin{itemize}
		\item [0.]  Set $\lam=\lam_0$ and $k=1$;
	    \item[1.] Compute 
	    \begin{equation}\label{def:x}
	        x =\underset{u\in  \R^n}\argmin
		\left\lbrace  \ell_f(u;\hat x_{k-1})+h(u) +\frac{1}{2\lam} \|u- \hat x_{k-1} \|^2 \right\rbrace;
	    \end{equation}
        if $\phi(x) - \phi_* \le \bar \varepsilon$, then {\bf stop};
		\item[2.]  {\bf If} the inequality $$f(x)-\ell_f(x;\hat x_{k-1}) - \frac{1-\chi}{2\lam} \|x-\hat x_{k-1}\|^2 \le \frac{(1-\chi) \bar \varepsilon}2$$ does not hold, {\bf then} set $\lam = \lam/2$ and go to step~1; {\bf else}, 
        set $\lam_k=\lam$, $\hat x_k=x$,  $k\leftarrow k+1$, and go to step 1.
	\end{itemize}
	\rule[0.5ex]{1\columnwidth}{1pt}


\begin{equation}\label{eq:ProbIntro}
	\phi_{*}:=\min \left\{\phi(x): x \in \R^n\right\}
	\end{equation}

where $\phi \in \bConv{n}$.


	 Black-box (BB)
     $(x^-,\chi,\varepsilon)$

	\noindent\rule[0.5ex]{1\columnwidth}{1pt}
    {\bf Input:}  $(x^-,\chi,\varepsilon) \in \dom \phi \times [0,1) \times \R_{++}$.

    \vgap

    \noindent
    {\bf Output:}
    $(x,y,\Gamma,\lam) \in \dom \phi \times \dom \phi \times \bConv{n} \times \R_{++}$ satisfying $\Gamma \le \phi$,
\begin{equation}\label{propyb}
    \phi(y)+\frac{\chi}{2 \lambda}\|y-x^-\|^2 - \underset{u\in\R^n}\min\left\{\Gamma(u) + \frac{1}{2\lam}\|u- x^- \|^2\right\} \le \varepsilon,
\end{equation}
and
\beq 
    x = \underset{u\in\R^n} \argmin \left\lbrace \Gamma(u) + \frac{1}{2\lam}\|u- x^- \|^2 \right\rbrace. \label{defxhatk}
     \eeq


where 
\begin{equation}\label{eq:sigma}
    \sigma = \sigma(\mu,\nu) := \frac{\lam[\nu(1+\mu \lam)+\chi(\mu-\nu)]}{1+\mu  \lambda+\chi  \lambda(\nu-\mu)}.
\end{equation} 


