    \item[1.] Compute 
$(\hat x_k, \hat y_k, \hat \Gamma_k, \lambda_k) = \BB(\hat x_{k-1},\chi, (1-\chi) \bar \varepsilon/2)$;

		\item[2.]
  Check whether $\phi(\hat y_k) - \phi_* \le \bar \varepsilon$ and if so {\bf stop}; else set $k\leftarrow k+1$ and go to step 1.
  % \item[3.]
		% Set $k\leftarrow k+1$ and go to step 1.
	\end{itemize}
