\begin{theorem}\label{thoutercs}
% Let $\chi \in [0,1)$ and tolerance $\bar \varepsilon>0$ be given, and
% consider U-CS with $\varepsilon = (1-\chi)\bar \varepsilon/2$.
U-CS terminates in at most
\begin{equation}\label{complprimal-2}
\min\left\{\min\left[ \frac{1}{\chi}\left(1+\frac{Q({\bar \varepsilon})}{\bar \varepsilon \mu_{\phi}}\right),  1+\frac{Q({\bar \varepsilon})}{\bar \varepsilon \mu_h}\right]
\log \left(1+\frac{\mu_\phi d_0^2}{\bar \varepsilon}\right)\, , \, \frac{d_0^2 Q({\bar \varepsilon})}{{\bar \varepsilon}^2} \right\}+
\displaystyle \left \lceil 
2 \log \frac{\lambda_0 Q({\bar \varepsilon})}{\bar \varepsilon} \right \rceil
\end{equation}
iterations and
\begin{equation}\label{defQf}
Q({\bar \varepsilon})= \frac{8 M_f^2}{(1-\chi)^2}+ {\bar \varepsilon} \left( \lam_0^{-1} + 
\frac{2L_f}{(1-\chi)^2} \right).
\end{equation}
\end{theorem}

