proof.raw_tex:
\begin{lemma}\label{lem:lam}
If $\lam$ satisfies 
\begin{equation}\label{ineq:lam}
    \lam \le \frac{(1-\chi)^2 \bar \varepsilon}{ 4{M}_f^2 + \bar \varepsilon {L}_f},
\end{equation}
then the point $x=x_k(\lam)$ computed in \eqref{def:x} satisfies the inequality in step 2. As a consequence, if the initial prox stepsize $\lam_0$ is chosen to be the right hand side of \eqref{ineq:lam}, then $\lam$ remains constant throughout the method.
\end{lemma}

\begin{proof}
    Assume that $\lam$ satisfies \eqref{ineq:lam}. Using \eqref{ineq:est} with $(M_f, L_f, u,v)=(M_f, L_f, x,\hat x_{k-1})$ and the inequality 
    $2M_f \Delta - a \Delta^2 \leq M_f^2/a$ with
    $\Delta=\|x-\hat x_{k-1}\|$ and $a=(1-\chi-\lam L_f)/2\lam$, we have
    \begin{align*}
    f(x)-\ell_f(x;\hat x_{k-1}) +\frac{\chi-1}{2 \lambda}  \|x-\hat x_{k-1}\|^2
    &\stackrel{\eqref{ineq:est}}\le 2M_f \|x-\hat x_{k-1}\| + \frac{L_f}2 \|x-\hat x_{k-1}\|^2+\frac{\chi-1}{2 \lambda  }\|x-\hat x_{k-1}\|^2 \\
    &= 2M_f \|x-\hat x_{k-1}\| - \frac{1-\chi-\lam L_f}{2\lam} \|x-\hat x_{k-1}\|^2 \\
    &\le \frac{2\lam M_f^2}{1-\chi-\lam L_f} \stackrel{\eqref{ineq:lam}}\le \frac{(1-\chi)\bar \varepsilon}2, %\label{ineq:error}
    \end{align*}
    where the last inequality is due to
    \eqref{ineq:lam}.
    Hence, the lemma is proved.
\end{proof}

\begin{proposition}\label{propouter}
Assume that  $\phi \in \bConv{n}$ and let $\mu=\mu_\phi$.
Assume also that
$(x,y,\Gamma,\lam) = \BB(x^-,\chi,\varepsilon)$
for some $(x^-,\chi,\varepsilon) \in \dom \phi \times [0,1) \times \R^n_{++}$, and $\Gamma \in \nConv{n}$ for some $\nu \in [0,\mu]$.
Then, for every $u \in \R^n$, we have

% and $\zeta \in [0,\chi]$,
\begin{equation}\label{ineq:contraction}
    2 \lambda\left[\phi(y)-\phi(u)\right]  \le \frac{2\lam \varepsilon}{1-\chi} + \left\|x^- - u\right\|^2 - (1+\sigma) \|x-u\|^2,
\end{equation}
where 
\begin{equation}\label{eq:sigma}
    \sigma = \sigma(\mu,\nu) := \frac{\lam[\nu(1+\mu \lam)+\chi(\mu-\nu)]}{1+\mu  \lambda+\chi  \lambda(\nu-\mu)}.
\end{equation} 
\end{proposition}

\begin{theorem}\label{thouter}
% Assume that (F1) holds. Then,
The number of iterations performed by any instance of  FSCO that satisfies condition (F1) is bounded by
\begin{equation}\label{complprimal}
 \min\left\{\min\left[ \frac{1}{\chi}\left(1+\frac{1}{\underline{\lam} \mu}\right),  1+\frac{1}{\underline{\lam} \nu}\right] \log\left(1+ \frac{\mu d_0^2}{\bar \varepsilon}\right), \frac{d_0^2}{{\underline \lambda}{\bar \varepsilon}} \right\},
\end{equation}
where the scalars $\chi$ and $\bar \varepsilon$ are input to FSCO, $d_0$ is as in \eqref{defd0}, and
\begin{equation}\label{eq:nu}
    \mu=\mu_\phi, \quad \nu := \min \left\{ \mu_\phi \, , \, \inf_k \mu (\hat \Gamma_k) \right\}.
\end{equation}
${\rm (}$By convention, \eqref{complprimal} 
should be understood as being equal to $d_0^2/({\underline{\lambda}}{\bar{\varepsilon}})$ when $\mu=0$.${\rm )}$
\end{theorem}

\begin{proof}
It is straightforward to see from Lemma \ref{lem:sigma}(b) that $\sigma(\lam) \ge \underline \sigma := \sigma(\underline \lam)$ for $\lam \ge \underline \lam$, where $\sigma(\lam)$ denotes the $\sigma$ defined in \eqref{eq:sigma}, considered as a function of $\lam$.
Note that we invoke the oracle $(\hat x_k, \hat y_k, \hat \Gamma_k, \lambda_k) = \BB(\hat x_{k-1},\chi, (1-\chi) \bar \varepsilon/2)$ in step 1.
Using \eqref{ineq:contraction}, assumption (F1), and the observation that $\sigma(\lam_k) \ge \underline \sigma$, we have
\begin{equation}\label{ohiustb}
    2 \lambda_k\left[\phi(\hat y_k)-\phi(u)\right]  \le \lam_k \bar \varepsilon + \left\|\hat x_{k-1}-u\right\|^2 - (1+\underline \sigma) \|\hat x_k-u\|^2,
\end{equation}
