where 
\begin{equation}\label{def:sigma}
    \underline \sigma = \frac{\underline{\lam}[\nu(1+\mu \underline{\lam})+\chi(\mu-\nu)]}{1+\mu {\underline \lambda}+\chi {\underline \lambda}(\nu-\mu)},
\end{equation}
and $\mu$ and $\nu$ are as in \eqref{eq:nu}.
It is easy to see that \eqref{ohiustb} with $u=x_*$, where $x_*$ denotes the closest solution of \eqref{eq:ProbIntro} to the initial point $\hat x_0$, satisfies 
$$
	\gamma_k \eta_k \le \alpha_{k-1} - (1+\sigma)\alpha_k + \gamma_k \delta
$$
with
\begin{equation}\label{eq:parameter}
    \gamma_k = 2\lam_k, \quad \eta_k=\phi(\hat y_k) - \phi_*, \quad \alpha_k = \|\hat x_k-x_*\|^2, \quad \delta = \frac{\bar \varepsilon}{2}, \quad \sigma = \underline \sigma, \quad {\underline \gamma} = 2{\underline \lam},
\end{equation}
where ${\underline \gamma}$
satisfies $\gamma_k \geq {\underline \gamma}$.

Using Lemma \ref{lm:easyrecur1}(b) with the above parameters, Lemma \ref{lem:sigma}(c), and the definition of $\underline \sigma$ in \eqref{def:sigma} that the complexity to find a $\bar \varepsilon$-solution is
\begin{equation}\label{eq:complexity}
  \min\left\{\frac{1+\underline \sigma}{\underline \sigma} \log\left(1+ \frac{\underline\sigma d_0^2}{{\underline \lambda}{\bar \varepsilon}}\right), \frac{d_0^2}{{\underline \lambda}{\bar \varepsilon}} \right\} \le \min\left\{\min\left[ \frac{1}{\chi}\left(1+\frac{1}{\underline{\lam} \mu}\right),  1+\frac{1}{\underline{\lam} \nu}\right] \log\left(1+ \frac{\underline \sigma d_0^2}{{\underline \lambda}{\bar \varepsilon}}\right), \frac{d_0^2}{{\underline \lambda}{\bar \varepsilon}} \right\}.  
\end{equation}
% Moreover, using the definition of $\underline \sigma$ in \eqref{def:sigma} and the assumptions that $\chi\in [0,1)$ and $\nu \le \mu$, we have
% \[
% \frac{\underline \sigma}{\underline{\lam}} \stackrel{\eqref{def:sigma}}= \frac{\nu(1+\mu \underline{\lam})+\chi(\mu-\nu)}{1+\mu {\underline \lambda}+\chi {\underline \lambda}(\nu-\mu)} \le \frac{\nu(1+\mu \underline{\lam})+\mu-\nu}{1+\mu {\underline \lambda}+ {\underline \lambda}(\nu-\mu)} = \frac{\mu(1+\nu \underline{\lam})}{1+\nu {\underline \lambda}} = \mu.
% \]
Moreover, we note that $\underline \sigma \le \underline \lam \mu$ in view of the second inequality in Lemma \ref{lem:sigma}(a).
Finally, this observation and \eqref{eq:complexity} immediately imply the complexity in \eqref{complprimal}.
\end{proof}

\begin{lemma}\label{lemetab} 
Define 
 \begin{align}
	 s &:= \frac{x^- - x}{\lam}, \label{defsb}\\
	 \eta &:= \phi(y) - \Gamma(x) - \inner{s}{y- x}. \label{defetab}
	\end{align}

Then, the following statements hold:
\begin{itemize}
\item[a)]
  $s \in \partial \Gamma (x)$, i.e., for every $u \in \R^n$,
 \begin{equation}\label{eq:subdifb}
    \Gamma(u) \ge \Gamma(x) + \inner{s}{u-x}; 
 \end{equation}  
  \item[b)] $s \in \partial_{\eta} \phi(y)$ and
  \begin{equation}\label{ineqetab}
  0 \le 2 \lam \eta \le  2 \lam \varepsilon - 
	    \|y- x\|^2 + (1-\chi)\|y- x^-\|^2.
     \end{equation}
\end{itemize}
\end{lemma}

\begin{proof} 
 (a) The optimality condition of \eqref{defxhatk} yields $0 \in \partial \Gamma_k(x) +(x-x^-)/\lambda$, which together with the definition of $s$ in \eqref{defsb} implies that the inclusion in a) holds.
 Relation \eqref{eq:subdifb} immediately follows from the inclusion in a) and the definition of the subdifferential.

(b) The relation $\phi \geq \Gamma$ (see step 1 of FSCO), \eqref{eq:subdifb}, the definition of $\eta$ in \eqref{defetab} imply that for every $u\in \dom \phi$,
	\[
	\phi(u) \ge \Gamma(u) \stackrel{\eqref{eq:subdifb}}\ge  \Gamma(x) + \inner{s}{u- x}
      \stackrel{\eqref{defetab}}=  \phi(y) + \inner{s}{u- y} - \eta,
	\]
which yields the inclusion in b). 
Taking $u=y$ in the above inequality gives $\eta \ge 0$, and hence the first inequality in \eqref{ineqetab} holds.
Using the definitions of $s$ and $\eta$ in \eqref{defsb} and \eqref{defetab}, respectively, and \eqref{propyb} and \eqref{defxhatk}, we have
