\begin{proposition}\label{lem:ACSCS}
The following statements hold for U-CS:
    \begin{itemize}
    \item[a)] $\{\lam_k\}$ is a non-increasing sequence;
        \item[b)] for every $k\ge 1$, we have
        \begin{align}
		&\hat x_k =\underset{u\in  \R^n}\argmin
		\left\lbrace  \ell_f(u;\hat x_{k-1})+h(u) +\frac{1}{2\lam_{k}} \|u- \hat x_{k-1} \|^2 \right\rbrace, \label{eq:sub1cs} \\
		&f(\hat x_{k}) -\ell_f(\hat x_{k};\hat x_{k-1})+\frac{\chi-1}{2 \lambda_{k}}\|\hat x_{k}-\hat x_{k-1}\|^2 \le \frac{(1-\chi)\bar \varepsilon}2,
  \label{ineq:iterationcs}\\
   & \lam_k \ge \min \left \lbrace \frac{(1-\chi)^2 \bar \varepsilon}{8 M_f^2 + 2 \bar \varepsilon L_f}, \lam_0 \right\rbrace.\label{ineq:lamj2}
	    \end{align}


       \item[c)]     U-CS is a special case of FSCO where:
    \begin{itemize}
        \item [i)]
        $\hat y_k=\hat x_k$ and $\hat \Gamma_k(\cdot)=\ell_f(\cdot;\hat x_{k-1})+h(\cdot)$
    for every $k \ge 1$;
    \item[ii)] assumption (F1) is satisfied with
    $\underline \lam$ given by \eqref{ineq:lamj2}.
    \end{itemize}

    \end{itemize}
    \end{proposition}

\begin{proof}
    a) This statement directly follows from the description of U-CS.

    b) Relations \eqref{eq:sub1cs} and \eqref{ineq:iterationcs} directly follow from the description of U-CS.
Next, we prove \eqref{ineq:lamj2}.
Supposing $\lam_{k-1}\le (1-\chi)^2 \bar \varepsilon/(4 M_f^2 + \bar \varepsilon L_f)$,
then it follows from Lemma \ref{lem:lam} that \eqref{ineq:iterationcs} holds with $\lam_k$ replaced by $\lambda_{k-1}$. This indicates that if $\lam$ is small enough, then it will remain unchanged. Therefore, following from the update scheme of $\lam$ in step 2 of U-CS, there is a lower bound as in \eqref{ineq:lamj2}.

c) Relations
  \eqref{eq:sub1cs}  and
     \eqref{ineq:iterationcs}
     are the analogues of
     relations \eqref{propyb} and  \eqref{defxhatk}
     of FSCO with 
$\hat y_k=\hat x_k$ and $\hat \Gamma_k$  as in (i).
Inequality \eqref{ineq:lamj2}
shows that Assumption (F1) is
satisfied. 
    \end{proof}

{\bf Proof of Theorem \ref{thoutercs}.}
Define 
\begin{equation}\label{defkbar}
\bar k=\left \lceil 2 \log \max\left\{\frac{ \lambda_0 (8M_f^2 + 2 \bar \varepsilon L_f) }{(1-\chi)^2 \bar \varepsilon},1\right\} \right \rceil.
\end{equation}
Observe that $\lambda_0/2^{k} \leq {\underline \lambda}$ for $k \geq \bar k$ where ${\underline{\lambda}}$ is given by the right-hand side of \eqref{ineq:lamj2},
and from Proposition \ref{lem:ACSCS} that we cannot halve $\lambda$ more than $\bar k$ iterations. 
It follows from \eqref{defkbar} and the definition of $ Q(\bar \varepsilon)$ in \eqref{defQf} that
\[
\bar k \leq  \displaystyle \left \lceil 
2 \log \frac{\lambda_0 Q({\bar \varepsilon})}{\bar \varepsilon} \right \rceil.
\]
Therefore, the second term on the right-hand side of \eqref{complprimal-2}
gives an upper bound on the number of iterations with backtracking of $\lambda$.
We now provide a bound on the number of remaining iterations to obtain a $\bar \varepsilon$-solution with U-CS.
In the $k$-th iteration of U-CS, the model $\hat \Gamma_k$ for $\phi=f+h$ is simply $\ell_f(\cdot,\hat x_{k-1})+h(\cdot)$ where $\ell_f$ is the linearization of $f$ as in \eqref{linfdef}, hence $\mu(\hat \Gamma_k) = \mu_h \le \mu_\phi$ and $\nu=\mu_h$ in \eqref{eq:nu}.
Since Proposition \ref{lem:ACSCS} shows that U-CS is a special case of FSCO, Theorem~\ref{thouter} immediately gives for U-CS the upper bound \eqref{complprimal} with ${\underline{\lambda}}$ given by \eqref{ineq:lamj2}
on the number of the remaining iterations
(where $\lambda$ is not halved)
required to find a $\bar \varepsilon$-solution 
of \eqref{eq:ProbIntro2}.
Using the inequality
\begin{equation}\label{upperlbar}
\frac{1}{\underline{\lam}} \stackrel{\eqref{ineq:lamj2}}=\max \left \lbrace \frac{8 M_f^2 + 2 \bar \varepsilon L_f}{(1-\chi)^2 \bar \varepsilon}, \frac{1}{\lambda_0} \right\rbrace
\leq \frac{8 M_f^2 + 2 \bar \varepsilon L_f}{(1-\chi)^2 \bar \varepsilon} + \frac{1}{\lambda_0}
\end{equation}
and the definition of $ Q(\bar \varepsilon)$ in \eqref{defQf},
we conclude that
$1/\underline{\lam} \le 
Q(\bar \varepsilon)/\bar \varepsilon$.
This observation and \eqref{complprimal} with ${\underline{\lambda}}$ given by \eqref{ineq:lamj2} thus imply that the first term in \eqref{complprimal-2} is an upper bound on the number of the remaining iterations
(where $\lambda$ is not halved).
This completes the proof.
\QEDA


