\begin{lemma} \label{lm:easyrecur1}
		Assume that sequences $\{\gamma_j\}$, $\{\eta_j\}$, and  $\{\alpha_j\}$ satisfy for every $j\ge 1$, $\gamma_j \ge {\underline \gamma}$ and 
		\beq \label{eq:easyrecur1}
		\gamma_j \eta_j \le \alpha_{j-1} - (1+\sigma)\alpha_j + \gamma_j \delta
		\eeq
  for some $\sigma \ge 0$, $\delta \ge 0$ and ${\underline \gamma} > 0$. Then, the following statements hold:
	\begin{itemize}
            \item[a)] for every $k\ge 1$,
            \begin{equation}\label{ineq:eta}
            \min_{1\le j \le k}  \eta_j \le \frac{\alpha_0 - (1+\sigma)^k \alpha_k}{\sum_{j=1}^k (1+\sigma)^{j-1} \gamma_j} + \delta;
        \end{equation}
  %           \item[b)] if the sequence $\{\eta_j\}$ is nonnegative, then for every $k\ge 1$,
  %           \begin{equation}\label{ineq:alpha}
  %           \alpha_k \le \frac{\alpha_0}{(1+\sigma)^k}  +
		% \frac{\sum_{j=1}^k (1+\sigma)^{j-1}\gamma_j \delta}{(1+\sigma)^k};
  %       \end{equation}
		\item[b)]  if the sequence $\{\alpha_j\}$ is nonnegative, then $ \min_{1\le j \le k} \eta_j \le 2\delta $ for every $ k\ge 1$ such that
		\[
		k \ge \min \left\lbrace  \frac{1+\sigma}{\sigma} \log\left( \frac{\sigma \alpha_0}{{\underline \gamma}\delta} + 1 \right), \frac{\alpha_0}{{\underline \gamma}\delta} \right\rbrace
		\]
		with the convention that the first term is equal to the second term
		when $\sigma=0$. (Note  that the first term converges to the second term
		as $\sigma \downarrow 0$.)
	\end{itemize}
\end{lemma}

\begin{proof}
	a) Multiplying \eqref{eq:easyrecur1} by $ (1+\sigma)^{j-1} $ and summing the resulting inequality from $ j=1 $ to $ k $, we have
	\begin{align}
	    \sum_{j=1}^k (1+\sigma)^{j-1} \gamma_j \left[ \min_{1\le j \le k}  \eta_j \right] &\le \sum_{j=1}^k (1+\sigma)^{j-1} \gamma_j \eta_j
     \le  \sum_{j=1}^k (1+\sigma)^{j-1} \left(  \alpha_{j-1} - (1+\sigma) \alpha_j + \gamma_j \delta \right) \nn \\
		 &=  \alpha_0 - (1+\sigma)^k \alpha_k +
		\sum_{j=1}^k (1+\sigma)^{j-1}\gamma_j \delta. \label{ineq:sum}
	\end{align}
        Inequality \eqref{ineq:eta} follows immediately from the above inequality.

        % b) This statement follows immediately from \eqref{ineq:sum} and the fact that $\eta_j\ge 0$.

        b) It follows from \eqref{ineq:eta}, and the facts that $\alpha_k\ge 0$ and $\gamma_j \ge {\underline \gamma}$ that
        \begin{equation}\label{ineq:eta1}
            \min_{1\le j \le k}  \eta_j  \le \frac{\alpha_0}{{\underline \gamma} \sum_{j=1}^k (1+\sigma)^{j-1}} + \delta.
        \end{equation}
	Using the fact that $ 1+\sigma \ge e^{\sigma/(1+\sigma)} $
	for every $\sigma \ge 0$, 
	we have
	\begin{equation}\label{ineq:theta}
	    \sum_{j=1}^{k} (1+\sigma)^{j-1} = \max \left\lbrace \frac{(1+\sigma)^k-1}{\sigma}, k \right\rbrace \ge \max\left\lbrace \frac{e^{\sigma k /(1+\sigma)} - 1}{\sigma}, k\right\rbrace.
	\end{equation}
	Plugging the above inequality into \eqref{ineq:eta1}, we have for every $ k\ge 1 $,
	\[
	\min_{1\le j \le k}  \eta_j \le \frac{\alpha_0}{{\underline \gamma}}\min \left\lbrace \frac{\sigma}{e^{\sigma k /(1+\sigma)} - 1}, \frac 1k \right\rbrace + \delta,
	\]
	which can be easily seen to imply (b).
\end{proof}

\begin{lemma}\label{lem:sigma}
  For every $\chi \in [0,1)$, $\lam>0$, $\mu>0$, and $\nu \in [0,\mu]$, the 
  quantity $\sigma=\sigma(\mu,\nu;\lambda)$ defined in \eqref{eq:sigma} satisfies the following statements:
  \begin{itemize}
      \item[a)] $\lam [ \chi  \mu + (1-\chi)  \nu] \le \sigma \le \lam \mu$, and hence $\sigma \ge \lambda \nu$;
      \item[b)] the function $\lam >0 \mapsto \sigma(\mu,\nu;\lambda)$ is non-decreasing;
      \item[c)] there holds
      \[
      \frac{1+\sigma}{\sigma} \le \min\left\{ \frac{1}{\chi}\left(1+\frac{1}{\lam \mu}\right),  1+\frac{1}{\lam \nu}\right\}.
      \]
  \end{itemize}
\end{lemma}

\begin{proof}
    a) It follows from \eqref{eq:sigma} and the fact that $\nu \le \mu$ that
 \[
    \sigma - \lam \mu =\frac{\lam(\mu-\nu)(1+\lam \mu)(\chi-1)}{1+\mu  \lambda+\chi  \lambda(\nu-\mu)}
    \ge \frac{\lam(\mu-\nu)(1+\lam \mu)(\chi-1)}{1+\mu  \lambda} =
\lam(\mu-\nu)(\chi-1),
    \]
    and hence that $\sigma \ge \lam [ \chi  \mu + (1-\chi)  \nu]$. Moreover, the second inequality of (a) immediately follows from the first identity above and the facts that $\chi<1$ and $\nu \le \mu$.

    b) Viewing $\sigma=\sigma(\lam)$ in \eqref{eq:sigma} as a function of $\lam$, one can verify that
\[
\sigma(\lam) = \frac{\nu(1+\mu \lam)+\chi(\mu-\nu)}{\lam^{-1}+\mu +\chi (\nu-\mu)}
\]
is a non-decreasing function of $\lam$.

    c) It follows from the definition of $\sigma$ in \eqref{eq:sigma} that 
    \[
    \frac{1+\sigma}{\sigma} = \frac{(1+\nu {\lam})(1+\mu {\lam})}{{\lam}[\nu(1+ \mu {\lam})+\chi(\mu-\nu)]}.
    \]
    Hence, it suffices to prove that
\begin{equation}\label{ineq:combine}
    \frac{(1+\nu {\lam})(1+\mu {\lam})}{{\lam}[\nu(1+ \mu {\lam})+\chi(\mu-\nu)]} \le \min\left\{ \frac{1}{\chi}\left(1+\frac{1}{{\lam} \mu}\right),  1+\frac{1}{{\lam} \nu}\right\}. 
\end{equation}
Since $\chi \in [0,1)$, it is easy to verify that
\[
\frac{1+\nu {\lam}}{\nu(1+ \mu {\lam})+\chi(\mu-\nu)} \le \frac{1}{\chi \mu},
\]
and hence that
\[
\frac{(1+\nu {\lam})(1+\mu {\lam})}{{\lam}[\nu(1+ \mu {\lam})+\chi(\mu-\nu)]} \le \frac{1+ \mu {\lam}}{\chi {\lam} \mu} = \frac{1}{\chi}\left(1+\frac{1}{{\lam} \mu}\right).
\]
Moreover, noting that $\chi \in [0,1)$ and $\mu\ge \nu$, we also have 
\[
\frac{(1+\nu {\lam})(1+\mu {\lam})}{{\lam}[\nu(1+ \mu {\lam})+\chi(\mu-\nu)]} \le 1+\frac{1}{{\lam} \nu}.
\]
Combining the above two inequalities, we conclude that \eqref{ineq:combine} holds.
\end{proof}

