= -2\lam \inner{s}{u-y} \nn \\
\stackrel{\eqref{qphi-1}}\ge & 2 \lambda \left[\phi(y)- \phi(u)\right] + \chi (\mu -\nu) \lam \|u-y\|^2 -   \frac{2\lam \eta}{1-\chi} + \frac{\chi \nu \lam}{1-\chi} \|y - x\|^2 + \nu \lam\|u - x\|^2. \label{ineq:long}
\end{align}

Rearranging the terms in \eqref{ineq:long} and using Lemma \ref{lemetab}(b), we have
\begin{align}
&\left\|x^--u \right\|^2  - (1+\nu \lam)\|x-u\|^2  -2 \lambda \left[\phi(y)- \phi(u)\right] \nn \\
& \stackrel{\eqref{ineq:long}}\ge \|x^--y\|^2 + \left( \frac{\chi \nu \lam}{1-\chi} - 1 \right)\|x-y\|^2 + \chi (\mu -\nu) \lam \|u-y\|^2 -   \frac{2\lam \eta}{1-\chi} \nn \\
& \stackrel{\eqref{ineqetab}}\ge  -\frac{2 \lam \varepsilon}{1-\chi} + \frac{\chi(1+\nu \lambda)}{1-\chi} \|x-y\|^2 + \chi (\mu -\nu) \lam \|u-y\|^2. \label{ineq:imp}
\end{align}
Rearranging the terms in the above inequality, we have
\begin{align}
    2\lambda \left[\phi(y)- \phi(u)\right] \le& 
\frac{2 \lam \varepsilon}{1-\chi} + \left\|x^--u \right\|^2  - (1+\nu \lam)\|x-u\|^2 \nn \\
&- \chi \left(\frac{1+\nu \lam}{1-\chi} \|x-y\|^2 + (\mu -\nu) \lam \|u-y\|^2\right). \label{telescopic1}
\end{align}

\begin{lemma}\label{lemetab} 
Define 
 \begin{align}
	 s &:= \frac{x^- - x}{\lam}, \label{defsb}\\
	 \eta &:= \phi(y) - \Gamma(x) - \inner{s}{y- x}. \label{defetab}
	\end{align}

Then, the following statements hold:
\begin{itemize}
\item[a)]
  $s \in \partial \Gamma (x)$, i.e., for every $u \in \R^n$,
 \begin{equation}\label{eq:subdifb}
    \Gamma(u) \ge \Gamma(x) + \inner{s}{u-x}; 
 \end{equation}  
  \item[b)] $s \in \partial_{\eta} \phi(y)$ and
  \begin{equation}\label{ineqetab}
  0 \le 2 \lam \eta \le  2 \lam \varepsilon - 
	    \|y- x\|^2 + (1-\chi)\|y- x^-\|^2.
     \end{equation}
\end{itemize}
\end{lemma}

\begin{proof} 
 (a) The optimality condition of \eqref{defxhatk} yields $0 \in \partial \Gamma_k(x) +(x-x^-)/\lambda$, which together with the definition of $s$ in \eqref{defsb} implies that the inclusion in a) holds.
 Relation \eqref{eq:subdifb} immediately follows from the inclusion in a) and the definition of the subdifferential.

\begin{lemma}\label{lem:zeta}
    Let $\mu=\mu_\phi$ and assume that $\Gamma \in \nConv{n}$ for some $\nu \in [0,\mu]$.
    For any $\zeta \in [0,1)$ and every $u\in \dom \phi$, we have
     \begin{equation}\label{qphi-1}
    \phi(u) \ge \phi(y) + \inner{s}{u- y} + \frac{\zeta (\mu-\nu)}{2} \|u- y\|^2 - \frac{\eta}{1-\zeta} + \frac{\zeta}{1-\zeta} \frac{\nu}{2}\|y - x\|^2 + \frac{\nu}{2}\|u - x\|^2,
	\end{equation}
    where $s$ and $\eta$ are as in \eqref{defsb} and \eqref{defetab}, respectively.
\end{lemma}

\begin{proof}
    Define
\begin{equation}\label{eq:tilde}
    \tilde s = s + \nu(x^- - x), \quad \tilde \eta = \eta - \frac{\nu}{2}\|y - x\|^2, \quad \tilde \phi = \phi - \frac{\nu}{2}\|\cdot - x^-\|^2, \quad \tilde \Gamma = \Gamma - \frac{\nu}{2}\|\cdot - x^-\|^2.
\end{equation}
It follows from Lemma \ref{lemetab}(a) and the above definitions of $\tilde s$ and $\tilde \Gamma$ that
$\tilde s \in \partial \tilde \Gamma(x)$.
In view of \eqref{eq:tilde} and the assumption that $\Gamma \in \nConv{n}$ for some $\nu \in [0,\mu]$, we observe that $\tilde \Gamma$ is convex and $\tilde \phi \ge \tilde \Gamma$.
Hence, following a similar argument as in Lemma~\ref{lemetab}(b), we conclude that
$\tilde s \in \partial_{\tilde \eta} \tilde \phi(y)$.

\begin{lemma}\label{lem:app}
Assume that $\xi>0, \psi \in \bConv{n}$ and $Q \in \mathcal{S}_{++}^n$ are such that $\psi-$ $(\xi / 2)\|\cdot\|_Q^2$ is convex and let $(y, v, \eta) \in \R^n \times \R^n \times \R_{+}$be such that $v \in \partial_\eta \psi(y)$. Then, for any $\tau>0$,
    \begin{equation}\label{ineq:app}
        \psi(u) \ge \psi(y)+\inner{v}{u-y}-\left(1+\tau^{-1}\right) \eta+\frac{(1+\tau)^{-1} \xi}{2}\|u-y\|_Q^2 \quad \forall u \in \R^n .
    \end{equation}
\end{lemma}

